CREATE COLUMN TABLE "TEST_AP"."OTPR" ("AbsId" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(7) NOT NULL , "Descr" NVARCHAR(30), "Display" NVARCHAR(1) DEFAULT 'Y', "FieldID" INTEGER CS_INT, "Locked" NVARCHAR(1) DEFAULT 'N', "DataType" NVARCHAR(1) DEFAULT 'S', PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTPR_CODE" ON "TEST_AP"."OTPR" ( "Code" ASC )